Lemma fact_nowrap_sound : forall segs E M allkn e lo hi,
  know_ok segs E M allkn -> fact_nowrap allkn e hi = true ->
  (lo <= bv_unsigned (edenot E e) <= hi)%Z ->
  bv_unsigned (edenot E e) = (fst (lin_of e) + tden E (snd (lin_of e)))%Z.
Proof.
