Section Lookups.
Variable segs : list Segment.

(* [comment removed for export] *)
Lemma rdn_cons1 : forall mem (a : word) n b bs,
  rdn segs mem a 1 = Some [b] -> rdn segs mem (a + 1) n = Some bs ->
  rdn segs mem a (S n) = Some (b :: bs).
Proof.
