Lemma split_mod_core : forall (ua ur SA : Z) j,
  (0 <= j <= 64)%Z -> (SA mod 2 ^ j = 0)%Z -> eqm ua (SA + ur) ->
  (ua mod 2 ^ j = ur mod 2 ^ j)%Z.
Proof.
