Lemma testbit_pow_sub : forall a i n : Z, (0 <= i <= a)%Z -> (0 <= n)%Z ->
  Z.testbit (2 ^ a - 2 ^ i)%Z n = (Z.leb i n && Z.ltb n a)%bool.
Proof.
